namespace sv_82a34b86d4c44309bc706c966c18b6bd.Services;

public class AppointmentService
{
    private static readonly List<string> Doctors =
    [
        "Dr. Smith",
        "Dr. Johnson",
        "Dr. Patel",
        "Dr. Garcia"
    ];

    private static readonly Dictionary<string, List<string>> SelfPayDoctors = new()
    {
        // Dr. Smith does NOT accept self-pay; the others do.
        ["Dr. Johnson"] = [],
        ["Dr. Patel"] = [],
        ["Dr. Garcia"] = []
    };

    private static readonly List<string> AllTimeSlots =
    [
        "9:00 AM",
        "9:30 AM",
        "10:00 AM",
        "10:30 AM",
        "11:00 AM",
        "1:00 PM",
        "1:30 PM",
        "2:00 PM",
        "2:30 PM",
        "3:00 PM"
    ];

    public Task<List<string>> GetDoctorsAsync()
        => Task.FromResult(new List<string>(Doctors));

    public Task<List<string>> GetAvailableTimeSlotsAsync(string doctor, DateOnly date)
    {
        // Stub: return all slots for any doctor/date combination.
        return Task.FromResult(new List<string>(AllTimeSlots));
    }

    /// <summary>
    /// Validates server-side business rules. Returns field-level errors keyed by field name.
    /// An empty dictionary means validation passed.
    /// </summary>
    public Task<Dictionary<string, string>> ValidatePatientAsync(
        string email,
        string insuranceProvider,
        string doctor,
        string timeSlot)
    {
        var errors = new Dictionary<string, string>();

        // Outstanding balance check
        if (string.Equals(email, "taken@example.com", StringComparison.OrdinalIgnoreCase))
        {
            errors["Email"] = "Account has outstanding balance";
        }

        // Self-pay restriction
        if (insuranceProvider == "None" && !SelfPayDoctors.ContainsKey(doctor))
        {
            errors["Doctor"] = "Selected doctor does not accept self-pay patients";
        }

        // Race-condition: slot just taken
        if (timeSlot == "10:00 AM")
        {
            errors["TimeSlot"] = "This slot is no longer available";
        }

        return Task.FromResult(errors);
    }
}

@page "/book-appointment"
@rendermode InteractiveServer
@using sv_82a34b86d4c44309bc706c966c18b6bd.Services
@inject AppointmentService AppointmentSvc

<PageTitle>Book Appointment</PageTitle>

<h3>Book a Medical Appointment</h3>

<EditForm EditContext="editContext" OnValidSubmit="HandleSubmit" FormName="appointment">
    <DataAnnotationsValidator />

    @* ───── STEP 1 ───── *@
    <fieldset>
        <legend>Patient Information</legend>

        <div class="mb-3">
            <label class="form-label" for="patientName">Patient Name</label>
            <InputText id="patientName" class="form-control" @bind-Value="model.PatientName" />
            <ValidationMessage For="() => model.PatientName" />
        </div>

        <div class="mb-3">
            <label class="form-label" for="email">Email</label>
            <InputText id="email" class="form-control" @bind-Value="model.Email" />
            <ValidationMessage For="() => model.Email" />
        </div>

        <div class="mb-3">
            <label class="form-label" for="phone">Phone</label>
            <InputText id="phone" class="form-control" @bind-Value="model.Phone" />
            <ValidationMessage For="() => model.Phone" />
        </div>

        <div class="mb-3">
            <label class="form-label" for="insurance">Insurance Provider</label>
            <InputSelect id="insurance" class="form-select" @bind-Value="model.InsuranceProvider">
                <option value="">-- Select --</option>
                <option value="Aetna">Aetna</option>
                <option value="BlueCross">BlueCross</option>
                <option value="Cigna">Cigna</option>
                <option value="UnitedHealth">UnitedHealth</option>
                <option value="None">None</option>
            </InputSelect>
            <ValidationMessage For="() => model.InsuranceProvider" />
        </div>
    </fieldset>

    @if (!showStep2)
    {
        <button type="button" class="btn btn-primary" @onclick="ProceedToStep2">
            Next
        </button>
    }

    @* ───── STEP 2 ───── *@
    @if (showStep2)
    {
        <fieldset class="mt-4">
            <legend>Appointment Details</legend>

            <div class="mb-3">
                <label class="form-label" for="doctor">Preferred Doctor</label>
                <InputSelect id="doctor" class="form-select"
                             @bind-Value="model.Doctor"
                             @bind-Value:after="OnDoctorOrDateChanged">
                    <option value="">-- Select --</option>
                    @foreach (var doc in doctors)
                    {
                        <option value="@doc">@doc</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => model.Doctor" />
            </div>

            <div class="mb-3">
                <label class="form-label" for="date">Date</label>
                <InputDate id="date" class="form-control"
                           @bind-Value="model.Date"
                           @bind-Value:after="OnDoctorOrDateChanged" />
                <ValidationMessage For="() => model.Date" />
            </div>

            <div class="mb-3">
                <label class="form-label" for="timeSlot">Time Slot</label>
                <InputSelect id="timeSlot" class="form-select" @bind-Value="model.TimeSlot">
                    <option value="">-- Select --</option>
                    @foreach (var slot in timeSlots)
                    {
                        <option value="@slot">@slot</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => model.TimeSlot" />
            </div>

            <div class="mb-3">
                <label class="form-label" for="reason">Reason for Visit</label>
                <InputTextArea id="reason" class="form-control" rows="3" @bind-Value="model.Reason" />
                <ValidationMessage For="() => model.Reason" />
            </div>

            <button type="button" class="btn btn-outline-secondary me-2" @onclick="BackToStep1">
                Back
            </button>
            <button type="button" class="btn btn-primary me-2" @onclick="CheckAvailability">
                Check Availability
            </button>
            <button type="submit" class="btn btn-success" disabled="@(!availabilityChecked)">
                Submit
            </button>
        </fieldset>
    }
</EditForm>

@if (submitted)
{
    <div class="alert alert-success mt-4">
        Appointment booked successfully!
    </div>
}

@code {
    private AppointmentModel model = new();
    private EditContext editContext = default!;
    private ValidationMessageStore messageStore = default!;

    private bool showStep2;
    private bool availabilityChecked;
    private bool submitted;

    private List<string> doctors = [];
    private List<string> timeSlots = [];

    protected override async Task OnInitializedAsync()
    {
        editContext = new EditContext(model);
        messageStore = new ValidationMessageStore(editContext);

        // Clear custom errors when any field changes so the user can retry.
        editContext.OnFieldChanged += (_, args) =>
        {
            messageStore.Clear(args.FieldIdentifier);
            availabilityChecked = false;
            editContext.NotifyValidationStateChanged();
        };

        doctors = await AppointmentSvc.GetDoctorsAsync();
    }

    private void ProceedToStep2()
    {
        messageStore.Clear();

        // Validate only step-1 fields.
        var isValid = editContext.Validate();

        // After full validation, clear step-2 messages so they don't block step 1.
        ClearStep2Messages();
        editContext.NotifyValidationStateChanged();

        // Re-check: are there any remaining messages (step-1 only)?
        if (!editContext.GetValidationMessages().Any())
        {
            showStep2 = true;
        }
    }

    private void BackToStep1()
    {
        showStep2 = false;
        availabilityChecked = false;
    }

    private async Task OnDoctorOrDateChanged()
    {
        availabilityChecked = false;
        if (!string.IsNullOrEmpty(model.Doctor) && model.Date.HasValue)
        {
            timeSlots = await AppointmentSvc.GetAvailableTimeSlotsAsync(
                model.Doctor, DateOnly.FromDateTime(model.Date.Value));
        }
    }

    private async Task CheckAvailability()
    {
        messageStore.Clear();
        availabilityChecked = false;

        if (!editContext.Validate())
            return;

        var errors = await AppointmentSvc.ValidatePatientAsync(
            model.Email, model.InsuranceProvider, model.Doctor!, model.TimeSlot!);

        if (errors.Count > 0)
        {
            foreach (var (field, message) in errors)
            {
                var fi = editContext.Field(field);
                messageStore.Add(fi, message);
            }
            editContext.NotifyValidationStateChanged();
            return;
        }

        availabilityChecked = true;
    }

    private async Task HandleSubmit()
    {
        if (!availabilityChecked)
            return;

        submitted = true;
    }

    private void ClearStep2Messages()
    {
        messageStore.Clear(editContext.Field(nameof(AppointmentModel.Doctor)));
        messageStore.Clear(editContext.Field(nameof(AppointmentModel.TimeSlot)));
        messageStore.Clear(editContext.Field(nameof(AppointmentModel.Date)));
        messageStore.Clear(editContext.Field(nameof(AppointmentModel.Reason)));
    }

    // ───── Model ─────

    private sealed class AppointmentModel
    {
        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Patient name is required.")]
        public string PatientName { get; set; } = "";

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Email is required.")]
        [System.ComponentModel.DataAnnotations.EmailAddress(ErrorMessage = "Invalid email format.")]
        public string Email { get; set; } = "";

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Phone is required.")]
        public string Phone { get; set; } = "";

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Insurance provider is required.")]
        public string InsuranceProvider { get; set; } = "";

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Doctor is required.")]
        public string? Doctor { get; set; }

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Date is required.")]
        [FutureDate(ErrorMessage = "Date must be in the future.")]
        public DateTime? Date { get; set; }

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Time slot is required.")]
        public string? TimeSlot { get; set; }

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Reason is required.")]
        [System.ComponentModel.DataAnnotations.MaxLength(500, ErrorMessage = "Reason cannot exceed 500 characters.")]
        public string Reason { get; set; } = "";
    }

    private sealed class FutureDateAttribute : System.ComponentModel.DataAnnotations.ValidationAttribute
    {
        protected override System.ComponentModel.DataAnnotations.ValidationResult? IsValid(
            object? value, System.ComponentModel.DataAnnotations.ValidationContext ctx)
        {
            if (value is DateTime dt && dt.Date <= DateTime.Today)
                return new System.ComponentModel.DataAnnotations.ValidationResult(
                    ErrorMessage, [ctx.MemberName!]);

            return System.ComponentModel.DataAnnotations.ValidationResult.Success;
        }
    }
}

